/**
 * 候选图片预处理节点 (v3.0 - Google Search)
 * 对 Google Custom Search API 返回的图片进行预处理和格式标准化
 */

// 可配置参数
const MIN_WIDTH = 680; // 最小宽度要求

/**
 * 筛选并标准化Google图片搜索结果
 * @param {Array} items - Google Custom Search API返回的items数组
 * @returns {Object} 包含筛选和标准化后的图片数组及URL列表
 */
function preprocessGoogleImages(items) {
  // 检查输入是否有效
  if (!items || !Array.isArray(items)) {
    return { filteredPhotos: [], candidateUrls: [] };
  }

  // 1. 筛选出有效的、符合宽度要求的图片
  // 必须确保 item.image 存在，否则 item.image.width 会报错
  const validImageItems = items.filter(item =>
    item.image &&
    item.image.width >= MIN_WIDTH &&
    item.link
  );

  // 2. 将筛选后的Google图片数据，【标准化】成我们通用的图片对象格式
  // 这一步是关键，它确保了后续节点（如AI甄选）无需修改
  const normalizedPhotos = validImageItems.map(item => ({
    // 这个新结构模仿了Pexels的结构，以保证下游兼容性
    width: item.image.width,
    height: item.image.height,
    src: {
      original: item.link // Google的图片URL在顶层的'link'字段
    },
    alt: item.title, // 使用图片所在页面的标题作为alt文本
    photographer: item.displayLink, // 使用来源域名作为'摄影师'信息
    originalGoogleItem: item // 保留原始Google数据以备不时之需
  }));

  // 3. 从标准化后的图片对象中，提取URL列表
  const candidateUrls = normalizedPhotos.map(photo => photo.src.original);

  return {
    filteredPhotos: normalizedPhotos,
    candidateUrls,
  };
}

// --- 主处理逻辑 ---
try {
  const inputData = $input.all();

  // 检查是否有输入数据
  if (!inputData || inputData.length === 0) {
    throw new Error("No input data received.");
  }

  const firstInput = inputData[0];
  const apiResponse = firstInput.json;

  // 为了数据流的完整性，我们从Start节点获取原始输入（如articleTitle）并传递下去
  const originalInput = $('Start').first().json;

  // 检查Google API的响应格式是否正确
  if (!apiResponse || !apiResponse.items) {
    throw new Error("Invalid Google API response format. Missing 'items' array.");
  }

  const searchItems = apiResponse.items;

  // 执行图片预处理和标准化
  const result = preprocessGoogleImages(searchItems);

  // 检查是否有符合条件的候选图片
  if (result.candidateUrls.length === 0) {
    // 即使没有符合条件的，也返回一个标准错误结构，而不是中断流程
    return [{
      json: {
        error: "No suitable images found after filtering.",
        candidateUrls: [],
        filteredPhotos: [],
        originalPhotos: searchItems,
        originalInput
      }
    }];
  }

  // 返回成功的预处理结果
  return [{
    json: {
      error: null,
      candidateUrls: result.candidateUrls,
      filteredPhotos: result.filteredPhotos,
      originalPhotos: searchItems, // 注意：这里现在是原始的Google items
      originalInput
    }
  }];

} catch (error) {
  // 处理意外错误，返回一个标准的错误对象
  return [{
    json: {
      error: `Processing error: ${error.message}`,
      candidateUrls: [],
      filteredPhotos: [],
      originalPhotos: [],
      originalInput: $('Start').first().json || null
    }
  }];
}

// 1. 获取上一个AI节点返回的完整数据对象
const aiOutput = $input.item.json;

// --- 智能路径判断 ---
// 这个变量用来存放我们最终要解析的字符串
let markdownString;

// 2. 检查是否存在复杂的 response.generations 路径
if (aiOutput.response && aiOutput.response.generations && aiOutput.response.generations.length > 0) {
  // 如果是复杂结构，就按复杂路径去取值
  console.log("检测到复杂输出格式，正在按复杂路径解析...");
  markdownString = aiOutput.response.generations[0][0].text;
} 
// 3. 如果复杂路径不存在，再检查是否存在简单的 .text 路径
else if (aiOutput.text) {
  // 如果是简单结构，就直接从 .text 取值
  console.log("检测到简单输出格式，正在按简单路径解析...");
  markdownString = aiOutput.text;
} 
// 4. 如果两种格式都不是，就抛出错误，防止流程继续
else {
  throw new Error("无法识别的AI输出格式，既没有找到 .text 也没有找到 .response.generations");
}

// --- 后续处理代码保持不变 ---

// 5. 清理 AI 返回的文本中可能包含的Markdown格式
const cleanJsonString = markdownString.replace(/```json\n|```/g, '');

// 6. 解析干净的JSON字符串
const aiDecision = JSON.parse(cleanJsonString);

// 7. 提取我们需要的索引号
const bestImageIndex = aiDecision.bestImageIndex;

// 8. 返回一个干净的、只包含索引号的输出
return {
  json: {
    bestImageIndex: bestImageIndex
  }
};

